package vn.somehouse;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.jdbc.core.JdbcTemplate;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import jakarta.validation.Validation;
class CatalogValidationTest {
 @Test void accentInsensitiveSearchKeepsVietnameseUsable(){assertEquals("quy nhon phu tai",CatalogService.normal("Quy Nhơn Phú Tài"));}
 @Test void unsafeLocaleNeverBecomesSqlColumn(){var c=new CatalogService(mock(JdbcTemplate.class),new ObjectMapper());assertThrows(ApiException.class,()->c.list("PROPERTY",Map.of("locale","vi;DROP TABLE x"),false));}
 @Test void unsafeSortNeverBecomesSql(){var c=new CatalogService(mock(JdbcTemplate.class),new ObjectMapper());assertThrows(ApiException.class,()->c.list("PROPERTY",Map.of("sort","price;DROP TABLE x"),false));}
 @Test void pageSizeIsBounded(){assertThrows(ApiException.class,()->CatalogService.integer(Map.of("size","10000"),"size",12,1,50));assertThrows(ApiException.class,()->CatalogService.integer(Map.of("page","-1"),"page",0,0,100000));}
 @Test void htmlCannotRunScriptOrInlineHandlers(){String clean=CatalogService.safeHtml("<p onclick=alert(1)>Xin chào</p><script>alert(1)</script><a href=javascript:alert(1)>Link</a><img src=/image/somehouse-icon.svg onerror=alert(1)>");assertTrue(clean.contains("Xin chào"));assertTrue(clean.contains("/image/somehouse-icon.svg"));assertFalse(clean.contains("onclick"));assertFalse(clean.contains("javascript:"));assertFalse(clean.contains("<script"));assertFalse(clean.contains("onerror"));}
 @Test void imagePathsCannotEscapeStorage(){for(String v:List.of("//evil.example/a.jpg","javascript:alert(1)","/uploads/../secret"))assertThrows(ApiException.class,()->CatalogService.asset(v));}
 @Test void seedIsValidAndProjectsAreResolved()throws Exception{var mapper=new ObjectMapper().findAndRegisterModules();var root=mapper.readTree(getClass().getResourceAsStream("/seed.json"));var validator=Validation.buildDefaultValidatorFactory().getValidator();Set<String> projects=new HashSet<>();int properties=0,articles=0;for(var n:root.path("items"))if(n.path("kind").asText().equals("PROJECT"))projects.add(n.path("slug").asText());for(var n:root.path("items")){var input=mapper.treeToValue(n,ApiTypes.ItemInput.class);assertTrue(validator.validate(input).isEmpty(),input.slug()+" "+validator.validate(input));if(input.kind().equals("PROPERTY")){properties++;assertTrue(projects.contains(input.projectSlug()));}if(input.kind().equals("ARTICLE")){articles++;assertEquals("Somehome",input.data().path("authorName").asText());}}assertEquals(58,properties);assertEquals(7,articles);assertEquals("0972 158 609",root.path("settings").path("phone").asText());}
}
